<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$me=require_login();$orders=mp550_orders(['buyer'=>(int)$me['id']],100);$selected=(int)($_GET['id']??0);$detail=$selected?mp550_order($selected):null;if($detail&&(int)$detail['buyer_user_id']!==(int)$me['id'])$detail=null;mp550_public_header('My Orders');
?>
<section class="mp550-page-head"><div><span>MY ORDERS</span><h1>Track every seller order in one place.</h1><p>Multi-vendor checkout is separated into individual seller orders for clear fulfilment and tracking.</p></div><b><?=count($orders)?> orders</b></section><?php if(!empty($_GET['placed'])):?><div class="mp550-alert ok">Order placed successfully. Sellers can now see and process their assigned orders.</div><?php endif;?><section class="mp550-orders-layout"><div class="order-list"><?php foreach($orders as $o):?><a class="order-card <?=$selected===(int)$o['id']?'active':''?>" href="?id=<?=(int)$o['id']?>"><div><span><?=e($o['order_number'])?></span><b><?=e($o['shop_name']?:$o['seller_name'])?></b><small><?=e(date('d M Y · h:i A',strtotime($o['placed_at'])))?></small></div><div><strong><?=mp550_money((float)$o['grand_total'])?></strong><em class="status <?=e($o['status'])?>"><?=e(ucfirst($o['status']))?></em></div></a><?php endforeach;?><?php if(!$orders):?><div class="mp550-empty"><b>No orders yet</b><span>Your marketplace orders will appear here.</span><a class="mp550-btn" href="/shop.php">Browse products</a></div><?php endif;?></div><aside class="order-detail"><?php if($detail):?><div class="detail-head"><div><span><?=e($detail['order_number'])?></span><h2><?=e($detail['shop_name']?:$detail['seller_name'])?></h2></div><em class="status <?=e($detail['status'])?>"><?=e(ucfirst($detail['status']))?></em></div><div class="timeline"><?php foreach($detail['log'] as $l):?><div><i></i><span><b><?=e(ucfirst($l['new_status']))?></b><small><?=e($l['note']?:date('d M · h:i A',strtotime($l['created_at'])))?></small></span></div><?php endforeach;?></div><h3>Items</h3><?php foreach($detail['items'] as $it):?><div class="review-item"><span><?=e($it['title'])?> × <?=(int)$it['quantity']?></span><b><?=mp550_money((float)$it['line_total'])?></b></div><?php endforeach;?><div class="checkout-total"><span>Total</span><b><?=mp550_money((float)$detail['grand_total'])?></b></div><div class="order-meta"><span><b>Payment</b><?=e(ucfirst(str_replace('_',' ',$detail['payment_method'])))?> · <?=e($detail['payment_status'])?></span><span><b>Delivery</b><?=e($detail['shipping_address']?:'Not provided')?></span><?php if($detail['tracking_number']):?><span><b>Tracking</b><?=e($detail['courier_name'].' '.$detail['tracking_number'])?></span><?php endif;?></div><?php else:?><div class="select-order">Select an order to view details.</div><?php endif;?></aside></section>
<?php mp550_public_footer(); ?>
